const express = require('express');
const pool = require('./db');
require('dotenv').config();

const app = express();
app.use(express.json());

// Health check endpoint
app.get('/', (req, res) => {
  res.json({ message: 'Newtonite Ops API is running' });
});

// Fetch all tasks
app.get('/tasks', async (req, res) => {
  try {
    const result = await pool.query('SELECT * FROM tasks ORDER BY id ASC');
    res.json(result.rows);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Update task with Optimistic Locking (version check)
app.put('/tasks/:id', async (req, res) => {
  const { id } = req.params;
  const { title, description, status, assigned_to, version } = req.body;

  try {
    const result = await pool.query(
      `UPDATE tasks 
       SET title = $1, description = $2, status = $3, assigned_to = $4, version = version + 1, updated_at = CURRENT_TIMESTAMP
       WHERE id = $5 AND version = $6
       RETURNING *`,
      [title, description, status, assigned_to, id, version]
    );

    if (result.rowCount === 0) {
      return res.status(409).json({ 
        error: 'Conflict: Task was modified by another request (Version Mismatch)' 
      });
    }

    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});